let cart = JSON.parse(localStorage.getItem('cart')) || []; // Simulated Connection [cite: 189]

// Initialize Display [cite: 191]
function displayProducts(items) {
    const grid = document.getElementById('productGrid');
    grid.innerHTML = items.map(p => `
        <div class="card">
            <img src="${p.image}" alt="${p.name}">
            <h3>${p.name}</h3>
            <p>Category: ${p.category}</p>
            <p><strong>₹${p.price}</strong></p>
            <button class="add-btn" onclick="addToCart(${p.id})">Add to Cart</button>
        </div>
    `).join('');
}

// Filtering Logic [cite: 163]
function filterCategory(cat) {
    document.querySelectorAll('.filter-btn').forEach(btn => btn.classList.remove('active'));
    event.target.classList.add('active');

    const filtered = cat === 'All' ? products : products.filter(p => p.category === cat);
    displayProducts(filtered);
}

// Search Logic [cite: 160]
function handleSearch() {
    const query = document.getElementById('searchInput').value.toLowerCase();
    const result = products.filter(p => p.name.toLowerCase().includes(query));
    displayProducts(result);
}

// Cart Functionality [cite: 167, 192]
function addToCart(id) {
    const product = products.find(p => p.id === id);
    cart.push(product);
    updateCart();
    alert(`${product.name} added to cart!`);
}

function updateCart() {
    localStorage.setItem('cart', JSON.stringify(cart));
    document.getElementById('cartCount').innerText = cart.length;
    renderCartItems();
}

function renderCartItems() {
    const container = document.getElementById('cartItems');
    let total = 0;
    container.innerHTML = cart.map((item, index) => {
        total += item.price;
        return `
            <div class="cart-item">
                <p>${item.name} - ₹${item.price} 
                <button onclick="removeFromCart(${index})">Remove</button></p>
            </div>
        `;
    }).join('');
    document.getElementById('totalAmount').innerText = total;
}

function removeFromCart(index) {
    cart.splice(index, 1);
    updateCart();
}

function toggleCart() {
    const modal = document.getElementById('cartModal');
    modal.style.display = modal.style.display === 'block' ? 'none' : 'block';
}

function checkout() {
    if (cart.length === 0) return alert("Cart is empty!");
    alert("Order placed successfully! This simulates database entry.");
    cart = [];
    updateCart();
    toggleCart();
}

// Initial Load
displayProducts(products);
updateCart();